'use strict';

/*
 * The command line reference page (docs/reference/command-line.md) matches the code. Its four
 * tables are generated by scripts/docs-reference.js; this file holds the literal expectations on the
 * facts it reads, the units on the derivation logic, and the source-shape pins. Freshness, coverage
 * both ways, no-conflict, cell-count, style and privacy for these blocks are in
 * test/docs-reference.test.js.
 *
 * Tests that pass today and so prove nothing on their own (their evidence is the recorded mutation
 * that turns each red): the two bin/config pins, the init refusal pin, the page prose test and the
 * "no text entry gives a code column" test, all on the real repository. The scratch-literal units
 * are what show the derivation can fail.
 *
 * Residuals the tests cannot see: which commands read --json, --vault, --out and --site-config
 * (hand text, checked by grep when written), the flags of the config subcommands (given by hand,
 * config keeps no list), the serve default port of 8080, and the "With no command" section of the
 * page, which describes shouldLaunch by hand.
 */

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const path = require('path');

const gen = require('../scripts/docs-reference');
const textFile = require('../scripts/docs-reference-text');
const { COMMAND_FLAGS } = require('../src/cli/args');
const configCli = require('../src/cli/config');

const ROOT = path.join(__dirname, '..');
const read = (rel) => fs.readFileSync(path.join(ROOT, rel), 'utf8');

const CLI_BLOCKS = ['cli-commands', 'cli-global-flags', 'cli-flags', 'cli-subcommands'];

// ---- literal code facts ----

test('cli-commands: the nine commands in order, with the exit codes their help lists', () => {
  const rows = gen.codeFacts()['cli-commands'];
  assert.deepEqual(rows.map((r) => r.key), ['init', 'check', 'build', 'serve', 'status', 'config', 'update', 'remote', 'desktop']);
  assert.deepEqual(Object.fromEntries(rows.map((r) => [r.key, r.exits])), {
    init: '0, 1, 3',
    check: '0, 1, 2, 3',
    build: '0, 1, 2, 3',
    serve: '0, 1, 3',
    status: '0, 1, 3',
    config: '0, 1, 3',
    update: '0, 1, 4',
    remote: '0, 1, 3',
    desktop: '0, 1, 3',
  });
});

test('cli-global-flags: the eleven flags, and which take a value', () => {
  const rows = gen.codeFacts()['cli-global-flags'];
  assert.deepEqual(
    rows.map((r) => [r.key, r.takesValue]),
    [
      ['--help', 'no'], ['--version', 'no'], ['--notices', 'no'], ['--config', 'yes'], ['--json', 'no'], ['--quiet', 'no'],
      ['--no-color', 'no'], ['--campaign', 'yes'], ['--vault', 'yes'], ['--out', 'yes'], ['--site-config', 'yes'],
    ],
  );
});

test('cli-flags: the 29 own flags in order, update --version being the one override', () => {
  const rows = gen.codeFacts()['cli-flags'];
  assert.deepEqual(rows.map((r) => r.key), [
    'init --name', 'init --title', 'init --theme', 'init --yes', 'init --new-vault', 'init --system',
    'check --graph',
    'build --force-out', 'build --force-check', 'build --no-check',
    'serve --build', 'serve --port', 'serve --host', 'serve --admin', 'serve --preview-port',
    'update --check', 'update --pre', 'update --version',
    'remote --mode', 'remote --admin-url', 'remote --preview-url', 'remote --bind', 'remote --trusted-proxy', 'remote --port', 'remote --preview-port', 'remote --account',
    'desktop --port', 'desktop --preview-port', 'desktop --background',
  ]);
  const no = ['init --yes', 'check --graph', 'build --force-out', 'build --force-check', 'build --no-check', 'serve --build', 'serve --admin', 'update --check', 'update --pre', 'desktop --background'];
  for (const r of rows) assert.equal(r.takesValue, no.includes(r.key) ? 'no' : 'yes', r.key);
  assert.equal(rows.find((r) => r.key === 'update --version').takesValue, 'yes');
});

test('cli-subcommands: the 20 keys in order, and the flags the allow-lists give', () => {
  const rows = gen.codeFacts()['cli-subcommands'];
  assert.deepEqual(rows.map((r) => r.key), [
    'config list', 'config add', 'config remove', 'config set-default', 'config path', 'config edit',
    'remote show', 'remote set',
    'remote account add', 'remote account change', 'remote account reset', 'remote account remove', 'remote account rename', 'remote account list',
    'remote password', 'remote signout-all', 'remote off',
    'desktop set',
    'desktop run',
    'serve --admin',
  ]);
  const flags = Object.fromEntries(rows.map((r) => [r.key, r.flags]));
  assert.equal(flags['remote set'], '--config, --mode, --admin-url, --preview-url, --bind, --trusted-proxy, --port, --preview-port');
  assert.equal(flags['remote signout-all'], '--config, --account');
  assert.equal(flags['desktop set'], '--config, --port, --preview-port');
  assert.equal(flags['serve --admin'], '--admin, --campaign, --config, --vault, --port, --preview-port, --json');
  assert.equal(flags['remote show'], '--config');
  for (const key of ['config list', 'config add', 'config remove', 'config set-default', 'config path', 'config edit']) {
    assert.equal(flags[key], undefined, key);
  }
});

test('no text entry gives a column the code holds: exits, takesValue, or the flags of remote, desktop and serve --admin', () => {
  for (const block of CLI_BLOCKS) {
    for (const [key, entry] of Object.entries(textFile[block])) {
      assert.equal(entry.exits, undefined, `${block}.${key}`);
      assert.equal(entry.takesValue, undefined, `${block}.${key}`);
      if (!key.startsWith('config ')) assert.equal(entry.flags, undefined, `${block}.${key}`);
    }
  }
  for (const key of ['config list', 'config add', 'config remove', 'config set-default', 'config path', 'config edit']) {
    assert.equal(typeof textFile['cli-subcommands'][key].flags, 'string', key);
  }
});

// ---- units on scratch literals ----

const FAKE_HELP = (name) => `usage ${name}\n\nExit codes:\n  0  ok\n  3  bad\n`;
function fakeInputs(over = {}) {
  return {
    COMMAND_FLAGS: { a: ['help', 'v', 'x'], b: ['help', 'v', 'y'] },
    COMMON_FLAGS: ['help', 'v'],
    VALUE_FLAGS: new Set(),
    // Only ('b', 'v') needs a value; every other flag is fine.
    validateFlags: (command, flags) => {
      if (command === 'b' && flags.v === true) throw new Error('--v needs a value: b --v <value>');
    },
    HELP_BY_COMMAND: { a: [], b: [] },
    commandHelp: FAKE_HELP,
    ...over,
  };
}

test('cliFacts: exact rows from a fake two-command table, including one override row', () => {
  const facts = gen.cliFacts(fakeInputs());
  assert.deepEqual(facts['cli-commands'], [{ key: 'a', exits: '0, 3' }, { key: 'b', exits: '0, 3' }]);
  assert.deepEqual(facts['cli-global-flags'], [{ key: '--help', takesValue: 'no' }, { key: '--v', takesValue: 'no' }]);
  assert.deepEqual(facts['cli-flags'], [
    { key: 'a --x', takesValue: 'no' },
    { key: 'b --y', takesValue: 'no' },
    { key: 'b --v', takesValue: 'yes' }, // the override: a common flag the validator treats differently here
  ]);
});

test('cliFacts: a value flag in VALUE_FLAGS that the validator agrees on makes no override row', () => {
  const facts = gen.cliFacts(
    fakeInputs({
      VALUE_FLAGS: new Set(['v']),
      validateFlags: (command, flags) => {
        if (flags.v === true || flags.y === true) throw new Error('needs a value');
      },
    }),
  );
  assert.deepEqual(facts['cli-flags'].map((r) => [r.key, r.takesValue]), [['a --x', 'no'], ['b --y', 'yes']]);
  assert.deepEqual(facts['cli-global-flags'].map((r) => [r.key, r.takesValue]), [['--help', 'no'], ['--v', 'yes']]);
});

test('cliFacts throws on a command with no help, on help for a command with no flags, and rethrows any other validator error', () => {
  assert.throws(() => gen.cliFacts(fakeInputs({ HELP_BY_COMMAND: { a: [] } })), /command "b" has flags .* but no help/);
  assert.throws(() => gen.cliFacts(fakeInputs({ HELP_BY_COMMAND: { a: [], b: [], c: [] } })), /command "c" has help .* but no flags/);
  assert.throws(
    () =>
      gen.cliFacts(
        fakeInputs({
          validateFlags: () => {
            throw new Error('boom');
          },
        }),
      ),
    /^Error: boom$/,
  );
});

test('subcommandFacts expands the account verbs in place, takes flags from the allow-lists, and adds serve --admin last', () => {
  const rows = gen.subcommandFacts({
    configSubs: ['one'],
    remoteSubs: ['show', 'account', 'off'],
    accountVerbs: ['v1', 'v2'],
    remoteAllowed: { show: ['config'], account: ['config', 'z'], off: ['config'] },
    desktopAllowed: { set: ['config', 'p'] },
    adminAllowed: ['admin', 'q'],
  });
  assert.deepEqual(rows, [
    { key: 'config one' },
    { key: 'remote show', flags: '--config' },
    { key: 'remote account v1', flags: '--config, --z' },
    { key: 'remote account v2', flags: '--config, --z' },
    { key: 'remote off', flags: '--config' },
    { key: 'desktop set', flags: '--config, --p' },
    { key: 'serve --admin', flags: '--admin, --q' },
  ]);
});

test('subcommandFacts throws on a remote subcommand with no allow-list entry', () => {
  assert.throws(
    () =>
      gen.subcommandFacts({
        configSubs: [],
        remoteSubs: ['show', 'extra'],
        accountVerbs: [],
        remoteAllowed: { show: ['config'] },
        desktopAllowed: {},
        adminAllowed: [],
      }),
    /remote subcommand "extra" has no entry/,
  );
});

test('renderBlock cli-flags gives the exact markdown', () => {
  const facts = { 'cli-flags': [{ key: 'a --x', takesValue: 'no' }, { key: 'a --y', takesValue: 'yes' }] };
  const text = { 'cli-flags': { 'a --x': { what: 'does x', since: '0.5.0' }, 'a --y': { what: 'does y' } } };
  assert.equal(
    gen.renderBlock('cli-flags', { facts, text }),
    [
      '| Flag | Takes a value | What it does |',
      '|---|---|---|',
      '| `a --x` | no | *Since 0.5.0.* does x |',
      '| `a --y` | yes | does y |',
    ].join('\n'),
  );
});

test('renderBlock puts backticks round each item of a flags list and an exits list', () => {
  const sub = { 'cli-subcommands': [{ key: 'desktop set', flags: '--config, --port' }, { key: 'config path' }] };
  const subText = { 'cli-subcommands': { 'desktop set': { what: 'sets' }, 'config path': { flags: '--config', what: 'prints' } } };
  assert.equal(
    gen.renderBlock('cli-subcommands', { facts: sub, text: subText }),
    [
      '| Subcommand | Flags it accepts | What it does |',
      '|---|---|---|',
      '| `desktop set` | `--config`, `--port` | sets |',
      '| `config path` | `--config` | prints |',
    ].join('\n'),
  );
  const cmd = { 'cli-commands': [{ key: 'check', exits: '0, 1, 2, 3' }] };
  assert.equal(
    gen.renderBlock('cli-commands', { facts: cmd, text: { 'cli-commands': { check: { what: 'checks' } } } }).split('\n')[2],
    '| `check` | checks | `0`, `1`, `2`, `3` |',
  );
});

test('rows refuses a text entry that gives takesValue, exits or flags where the code has them', () => {
  const facts = { 'cli-flags': [{ key: 'a --x', takesValue: 'no' }] };
  assert.throws(() => gen.rows('cli-flags', { facts, text: { 'cli-flags': { 'a --x': { what: 'x', takesValue: 'yes' } } } }), /the code holds "takesValue"/);
  const cmd = { 'cli-commands': [{ key: 'check', exits: '0' }] };
  assert.throws(() => gen.rows('cli-commands', { facts: cmd, text: { 'cli-commands': { check: { what: 'x', exits: '0, 9' } } } }), /the code holds "exits"/);
  const sub = { 'cli-subcommands': [{ key: 'remote show', flags: '--config' }] };
  assert.throws(() => gen.rows('cli-subcommands', { facts: sub, text: { 'cli-subcommands': { 'remote show': { what: 'x', flags: '--mode' } } } }), /the code holds "flags"/);
});

// ---- source-shape pins (these read source text, not behaviour) ----

test('source-shape test: the case labels in bin/scriptorium.js are the commands in COMMAND_FLAGS', () => {
  const src = read('bin/scriptorium.js');
  const labels = [...src.matchAll(/case '([a-z-]+)': \{/g)].map((m) => m[1]);
  assert.deepEqual([...labels].sort(), Object.keys(COMMAND_FLAGS).sort());
  assert.equal(labels.length, 9);
});

test('source-shape test: the case labels in src/cli/config.js are the config SUBCOMMANDS, and the literal list', () => {
  const src = read('src/cli/config.js');
  const labels = [...src.matchAll(/case '([a-z-]+)':/g)].map((m) => m[1]);
  assert.deepEqual(labels, [...configCli.SUBCOMMANDS]);
  assert.deepEqual(labels, ['list', 'add', 'remove', 'set-default', 'path', 'edit']);
});

test('source-shape test: init refuses exactly --campaign, --site-config and --json', () => {
  const src = read('src/cli/init.js');
  const m = src.match(/for \(const flag of (\[[^\]]*\])\) \{\s*if \(flags\[flag\] !== undefined\) \{\s*throw new ConfigError\(`init does not accept --\$\{flag\}`\)/);
  assert.ok(m, 'the refusal loop in src/cli/init.js has changed shape');
  const list = [...m[1].matchAll(/'([a-z-]+)'/g)].map((x) => x[1]);
  assert.deepEqual(list, ['campaign', 'site-config', 'json']);
});

// ---- the page's hand-written prose that the generator cannot see ----

test('the page names the init refusals under "Flags most commands accept", and the old heading is gone', () => {
  const page = read('docs/reference/command-line.md');
  assert.match(page, /^## Flags most commands accept$/m);
  assert.doesNotMatch(page, /Flags every command accepts/);
  const start = page.indexOf('## Flags most commands accept');
  const section = page.slice(start, page.indexOf('\n## ', start + 1));
  for (const flag of ['campaign', 'site-config', 'json']) assert.ok(section.includes(`\`--${flag}\``), `--${flag}`);
  assert.match(section, /`init` refuses/);
  assert.match(section, /`serve --admin`/);
  assert.match(section, /`remote` and `desktop`/);
});

test('control: the pin patterns see a changed list in scratch source', () => {
  const scratch = "for (const flag of ['campaign', 'site-config', 'json', 'quiet']) {\n    if (flags[flag] !== undefined) {\n      throw new ConfigError(`init does not accept --${flag}`);";
  const m = scratch.match(/for \(const flag of (\[[^\]]*\])\) \{\s*if \(flags\[flag\] !== undefined\) \{\s*throw new ConfigError\(`init does not accept --\$\{flag\}`\)/);
  assert.ok(m);
  assert.deepEqual([...m[1].matchAll(/'([a-z-]+)'/g)].map((x) => x[1]), ['campaign', 'site-config', 'json', 'quiet']);
});
